<?php if (!defined('BASEPATH')) exit('No direct script access allowed');class Mastersetup extends CI_Controller {    public $companyid;    public $userid;    public $mysqldatetime;    public function __construct() {        parent::__construct();        $this->load->helper('xssclean');        $ArrUserLoggedInfo = fnGetUserLoggedInfo('1');        $this->companyid = $ArrUserLoggedInfo['companyid'];        $this->userid = $ArrUserLoggedInfo['id'];        $this->mysqldatetime = date('Y-m-d H:i:s');        $this->load->library('pagination');        fnIfCheckUserLoggedIn();        $this->limit = LIMITPERPAGE;    }    function managechecklist() {        $this->load->model(CNFCOMPANY . 'checklistmodel');        $ArrData['ArrStatus'] = unserialize(ARRSTATUS);        $VarFrom = xssclean($this->input->post('rfrom'));        $VarChecklist = xssclean($this->input->post('c'));        $VarStatus = xssclean($this->input->post('s'));        $clickedColumnId = xssclean($this->input->post('columnId'));        $newsortorder = xssclean($this->input->post('sortorder'));        $VarAfilter = xssclean($this->input->post('afilter'));        $ArrDbCols = array('c.description', 'status', 'u.contactname', 'c.dateupdated');        $ArrList = [];        if ($VarFrom == 1) {            $VarURLSegment = 4;            $config['base_url'] = base_url() . CNFCOMPANY . 'mastersetup/managechecklist/';            $config['total_rows'] = $this->checklistmodel->fnCount($VarChecklist, $VarStatus, $VarAfilter);            $config['per_page'] = $this->limit;            $config['uri_segment'] = $VarURLSegment;            $offset = $this->uri->segment($VarURLSegment);            $this->pagination->initialize($config);            $sortby = "dateupdated";            $sortorder = "desc";            if ($clickedColumnId <> '' && $newsortorder <> '') {                if (array_key_exists($clickedColumnId, $ArrDbCols)) {                    $sortby = $ArrDbCols[$clickedColumnId];                }                $sortorder = $newsortorder;            }            $ArrList = $this->checklistmodel->fnList($VarChecklist, $VarStatus, $this->limit, $offset, $sortby, $sortorder, $VarAfilter)->result();            $data['pagination'] = $this->pagination->create_linkswithajax('Checklist');            $i = 0;            $ArrFnlList = array();            $ArrStatus = unserialize(ARRSTATUS);            foreach ($ArrList as $ObjUnit) {                $ArrFnlList[$i]['id'] = $ObjUnit->id;                $ArrFnlList[$i]['d'] = $ObjUnit->description;                $ArrFnlList[$i]['ub'] = $ObjUnit->contactname;                $ArrFnlList[$i]['s'] = $ArrStatus[$ObjUnit->status];                $ArrFnlList[$i]['du'] = date('d-m-Y H:i:s', strtotime($ObjUnit->dateupdated));                $i = $i + 1;            }            echo json_encode(array('errcode' => 1, 'cn' => $config['total_rows'], 'ct' => $i, 're' => $ArrFnlList, 'pa' => base64_encode($data['pagination'])));            unset($ArrFnlList);            die;        } else {            $this->load->view(CNFCOMPANY . 'managechecklist', $ArrData);        }    }    function addeditchecklist() {        $this->load->model(CNFCOMPANY . 'checklistmodel');        $ArrData = array('ArrBasicInfo' => array(), 'VarId' => '');        $VarId = $this->uri->segment(4);        $ArrData['Edit'] = $this->uri->segment(5);        if ($VarId <> '' && base64_decode(urldecode($VarId))) {            $VarChecklistId = base64_decode(urldecode($VarId));            $ArrResults = $this->checklistmodel->fnGetInfo('', '', $VarChecklistId);            $ArrData['ArrRes'] = $ArrResults[0];            $ArrData['VarId'] = $ArrResults[0]['id'];        } else {        }        $this->load->view(CNFCOMPANY . 'addeditchecklist', $ArrData);    }    function updatechecklist() {        $VarLoggedUserId = fnGetUserLoggedInfo(1);        $this->load->model(CNFCOMPANY . 'checklistmodel');        $ArrResult = array();        $VarDesc = xssclean($this->input->post('d'));        $VarStatus = xssclean($this->input->post('s'));        $VarId = xssclean($this->input->post('id'));        if ($VarDesc <> '') {            $ArrUpdateData = array('id' => $VarId, 'companyid' => $VarLoggedUserId['companyid'], 'description' => $VarDesc, 'status' => $VarStatus,                'updatedby' => $VarLoggedUserId['id'], 'dateupdated' => date('Y-m-d H:i:s'));            if (empty($VarId)) {                $ArrUpdateData['datecreated'] = date('Y-m-d H:i:s');            }            $ArrResult = $this->checklistmodel->saveInfo($ArrUpdateData);        } else {            $ArrResult['errcode'] = -1;            $ArrResult['msg'] = 'Invalid Input!';        }        echo json_encode($ArrResult);    }    function changeCheckListStatus() {        $this->load->model(CNFCOMPANY . 'checklistmodel');        $VarActDeactOption = xssclean($this->input->post('actdeactFabType'));        $VarCid = xssclean($this->input->post('cid'));        if ($VarActDeactOption <> '' && $VarCid <> '') {            $this->checklistmodel->changeCheckListStatus($VarCid, $VarActDeactOption);        }        echo json_encode(array('errcode' => 1));        die;    }    function managemodeofenquiry() {        $this->load->model(CNFCOMPANY . 'mmodeofenquirymodel');        $ArrData['ArrStatus'] = unserialize(ARRSTATUS);        $VarFrom = xssclean($this->input->post('rfrom'));        $VarModeofEnquiry = xssclean($this->input->post('moe'));        $VarStatus = xssclean($this->input->post('s'));        $clickedColumnId = xssclean($this->input->post('columnId'));        $newsortorder = xssclean($this->input->post('sortorder'));        $ArrDbCols = array('c.modeofenquiry', 'c.status', 'u.contactname', 'c.dateupdated');        if ($VarFrom == 1) {            $VarURLSegment = 4;            $this->load->library('pagination');            $config['base_url'] = base_url() . CNFCOMPANY . 'mastersetup/managemodeofenquiry/';            $config['total_rows'] = $this->mmodeofenquirymodel->fnCount($VarModeofEnquiry, $VarStatus);            $config['per_page'] = $this->limit;            $config['uri_segment'] = $VarURLSegment;            $offset = $this->uri->segment($VarURLSegment);            $this->pagination->initialize($config);            $sortby = "dateupdated";            $sortorder = "desc";            if ($clickedColumnId <> '' && $newsortorder <> '') {                if (array_key_exists($clickedColumnId, $ArrDbCols)) {                    $sortby = $ArrDbCols[$clickedColumnId];                }                $sortorder = $newsortorder;            }            $ArrMerchantList = $this->mmodeofenquirymodel->fnList($VarModeofEnquiry, $VarStatus, $this->limit, $offset, $sortby, $sortorder)->result();            $data['pagination'] = $this->pagination->create_linkswithajax('Modeofenq');            $i = 0;            $ArrFnlList = array();            $ArrStatus = unserialize(ARRSTATUS);            foreach ($ArrMerchantList as $ObjUnit) {                $ArrFnlList[$i]['id'] = $ObjUnit->id;                $ArrFnlList[$i]['moe'] = $ObjUnit->modeofenquiry;                $ArrFnlList[$i]['ub'] = $ObjUnit->contactname;                $ArrFnlList[$i]['s'] = $ArrStatus[$ObjUnit->status];                $ArrFnlList[$i]['du'] = date('d-m-Y H:i:s', strtotime($ObjUnit->dateupdated));                $i = $i + 1;            }            echo json_encode(array('errcode' => 1, 'cn' => $config['total_rows'], 'ct' => $i, 're' => $ArrFnlList, 'pa' => base64_encode($data['pagination'])));            unset($ArrFnlList);            die;        } else {            $this->load->view(CNFCOMPANY . 'managemodeofequiry', $ArrData);        }    }    function addeditmodeofenquiry() {        $this->load->model(CNFCOMPANY . 'mmodeofenquirymodel');        $ArrData = array('ArrBasicInfo' => array(), 'VarId' => '');        $VarId = $this->uri->segment(4);        $ArrData['Edit'] = $this->uri->segment(5);        if ($VarId <> '' && base64_decode(urldecode($VarId))) {            $VarEnquiryTypeId = base64_decode(urldecode($VarId));            $ArrResults = $this->mmodeofenquirymodel->fnGetInfo('', '', $VarEnquiryTypeId);            $ArrData['ArrRes'] = $ArrResults[0];            $ArrData['VarId'] = $ArrResults[0]['id'];        } else {        }        $this->load->view(CNFCOMPANY . 'addeditmodeofenquiry', $ArrData);    }    function updatemodeofenq() {        $VarLoggedUserId = fnGetUserLoggedInfo(1);        $this->load->model(CNFCOMPANY . 'mmodeofenquirymodel');        $ArrResult = array();        $VarModeOfEnquiry = xssclean($this->input->post('moe'));        $VarStatus = xssclean($this->input->post('s'));        $VarId = xssclean($this->input->post('id'));        if ($VarModeOfEnquiry <> '') {            $ArrUpdateData = array('id' => $VarId, 'companyid' => $VarLoggedUserId['companyid'], 'modeofenquiry' => $VarModeOfEnquiry, 'status' => $VarStatus, 'updatedby' => $VarLoggedUserId['id'], 'dateupdated' => date('Y-m-d H:i:s'));            if ($VarId == '' || $VarId == 0) {                $ArrUpdateData['datecreated'] = date('Y-m-d H:i:s');            }            $ArrResult = $this->mmodeofenquirymodel->fnSaveInfo($ArrUpdateData);        } else {            $ArrResult['errcode'] = -1;            $ArrResult['msg'] = 'Invalid Input!';        }        echo json_encode($ArrResult);    }    function changemodeofenq() {        $this->load->model(CNFCOMPANY . 'mmodeofenquirymodel');        $VarActDeactOption = xssclean($this->input->post('actDeact'));        $VarCid = xssclean($this->input->post('cid'));        if ($VarActDeactOption <> '' && $VarCid <> '') {            $this->mmodeofenquirymodel->fnChangeStatus($VarCid, $VarActDeactOption);        }        echo json_encode(array('errcode' => 1));        die;    }}